const MAX_SIDECAR_BYTES = 8192;
const SIDECAR_SUFFIX = '.green.json';
const COA_GREEN_ALLOWLIST = ['lot_id','filename','sha256','moisture_pct','mesh_pass','spec_moisture_max','spec_mesh_required','salmonella_absent','spec_salmonella_required','tpc_cfu','spec_tpc_max','pyruvic_umol','spec_pyruvic_required','spec_pyruvic_min'];
const RED_FORBIDDEN = ['bytes','pdf','path','file_bytes','nextcloud_folder_path','vault_href'];
function assertBasename(name) {
  if (typeof name !== 'string' || !name) throw new Error('filename must be a basename with no path');
  if (name.includes('/') || name.includes('\\') || name.includes('..') || name.includes('\0')) {
    throw new Error('filename must be a basename with no path');
  }
}
function pdfBasenameFromSidecar(name) {
  if (!name.endsWith(SIDECAR_SUFFIX)) throw new Error('sidecar_basename must end with .green.json');
  const stem = name.slice(0, -SIDECAR_SUFFIX.length);
  assertBasename(stem);
  return stem;
}
function persistFields(payload) {
  if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
  for (const key of Object.keys(payload)) {
    if (RED_FORBIDDEN.includes(key)) throw new Error('RED COA key forbidden: ' + key);
    if (!COA_GREEN_ALLOWLIST.includes(key)) throw new Error('unknown COA key forbidden: ' + key);
    if (payload[key] != null && typeof payload[key] === 'object') throw new Error('nested objects forbidden');
  }
  if (typeof payload.lot_id !== 'number' || !Number.isInteger(payload.lot_id) || payload.lot_id < 1) throw new Error('lot_id must be a positive integer');
  assertBasename(payload.filename);
  if (typeof payload.sha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(payload.sha256)) throw new Error('sha256 must be 64 hex characters');
  for (const numKey of ['moisture_pct','spec_moisture_max','tpc_cfu','spec_tpc_max','pyruvic_umol','spec_pyruvic_min']) {
    if (typeof payload[numKey] !== 'number' || !Number.isFinite(payload[numKey])) throw new Error(numKey + ' must be a number');
  }
  for (const boolKey of ['mesh_pass','spec_mesh_required','salmonella_absent','spec_salmonella_required','spec_pyruvic_required']) {
    if (typeof payload[boolKey] !== 'boolean') throw new Error(boolKey + ' must be boolean');
  }
  const out = {};
  for (const key of COA_GREEN_ALLOWLIST) out[key] = key === 'sha256' ? String(payload.sha256).toLowerCase() : payload[key];
  return out;
}
function parseSidecarBytes(buf, trigger) {
  if (!Buffer.isBuffer(buf)) throw new Error('sidecar bytes required');
  if (buf.length > MAX_SIDECAR_BYTES) throw new Error('sidecar too large');
  if (buf.length >= 4 && buf.subarray(0, 4).toString('latin1') === '%PDF') throw new Error('RED PDF payload forbidden');
  if (buf.includes(0)) throw new Error('RED binary payload forbidden');
  let payload;
  try { payload = JSON.parse(buf.toString('utf8')); } catch { throw new Error('sidecar must be GREEN JSON'); }
  const persist = persistFields(payload);
  if (persist.lot_id !== trigger.lot_id) throw new Error('lot_id mismatch');
  if (persist.filename !== pdfBasenameFromSidecar(trigger.sidecar_basename)) throw new Error('filename mismatch');
  return persist;
}
const trigger = $('Allowlist sidecar trigger').first().json;
const item = $input.first();
let buf;
if (item.binary && Object.keys(item.binary).length) {
  const key = Object.keys(item.binary)[0];
  buf = Buffer.from(item.binary[key].data, 'base64');
} else {
  const raw = item.json;
  const status = raw.statusCode ?? raw.status;
  if (status && status !== 200) throw new Error('sidecar GET failed');
