  if (Number.isFinite(len) && len > MAX_SIDECAR_BYTES) throw new Error('sidecar too large');
  if (typeof raw.data === 'string') buf = Buffer.from(raw.data, 'utf8');
  else if (typeof raw.body === 'string') buf = Buffer.from(raw.body, 'utf8');
  else if (typeof raw === 'string') buf = Buffer.from(raw, 'utf8');
  else if (raw && typeof raw.body === 'object') buf = Buffer.from(JSON.stringify(raw.body), 'utf8');
  else if (raw && typeof raw.data === 'object') buf = Buffer.from(JSON.stringify(raw.data), 'utf8');
  else throw new Error('sidecar bytes required');
}
return [{ json: parseSidecarBytes(buf, trigger) }];
